__doc__ = """
Builder context objects used while lowering instructions into code containers.

The :class:`Context` class carries the transient state that a builder needs
while traversing the instruction tree. A context links together:

- the active symbolic :class:`InstructionEnvironment`,
- the active :class:`Namespace` used for routine-variable allocation,
- the current :class:`ComputeResource` stack,
- the current nesting level and naming path,
- the surrounding library and parent context.

Contexts are intentionally lightweight and are copied through
:meth:`Context.inherit` whenever the builder descends into a nested structure.
That makes the context the place where backend-independent lowering state is
threaded through the code-generation pipeline.
"""


class Context:
    """
    Carry builder state while the instruction tree is lowered.

    A context bundles the transient state that would otherwise have to be
    threaded through many builder calls individually. Child contexts inherit
    from their parent via :meth:`inherit`, reusing most state while optionally
    overriding the environment, namespace, or compute resource.
    """

    def __init__(
        self,
        /,
        *,
        # parent: CodeContainer | None = None,
        level: int = 0,
        environment: InstructionEnvironment | None = None,
        namespace: Namespace | None = None,
        # assignments: dict | None = None,
        name: str | None = None,
        resource: ComputeResource | None = None,
        # frame_selectors: Set[LibRoutineFrameSelectVariable] | None = None,
        _names: list[str] | None = None,
        _library=None,
        _parent_context: Self | None = None,
    ) -> None:
        """
        Initialize a builder context.

        :param level: Nesting depth in the generated container tree.
        :param environment: Active symbolic instruction environment.
        :param namespace: Active routine-variable namespace.
        :param name: Optional local name component appended to the context path.
        :param resource: Active compute resource or resource stack.
        :param _names: Internal accumulated name components inherited from the
            parent context.
        :param _library: Library currently being built.
        :param _parent_context: Parent context in the traversal chain.
        """
        if environment is None:
            environment = InstructionEnvironment()

        if namespace is None:
            namespace = Namespace()

        # if parent is None:
        #     self._parent = None
        # else:
        #     self._parent = ref(parent)

        # if resource is None:
        #     resource = DefaultComputeResource()

        # if frame_selectors is None:
        #     frame_selectors = set()

        self._container = None
        self._level = level
        self._namespace = namespace
        self._environment = environment
        self._resource = resource
        # self._assignments = assignments
        self._names = list(_names or [])
        # self._frame_selectors = frame_selectors
        self._parent_context = _parent_context

        if name is not None:
            self._names.append(name)

        self._library = _library

    # there is only one assignments instance being passed down a routine.

    @property
    def name(self) -> str:
        """Return the readable name assembled from the context path."""
        if self._names:
            return "_".join(self._names)
        return "_"

    def hashed_name(self, num_symbols: int = 8) -> str:
        """
        Return a shortened hash of the current context name.

        :param num_symbols: Number of hexadecimal characters to keep.
        :returns: Stable shortened hash string.
        """
        return sha256(self.name.encode("utf-8")).hexdigest()[:num_symbols]

    @property
    def parent(self) -> CodeContainer | None:
        """Return the nearest parent container, if one exists."""
        # if self._parent is None:
        #     return None
        # # weakref
        # return self._parent()
        if self.parent_context is None:
            return None
        container = self.parent_context.container
        if container is not None:
            return container
        return self.parent_context.parent

    @property
    def parent_context(self) -> Self | None:
        """Access the parent context in the traversal chain."""
        return self._parent_context

    @property
    def level(self) -> int:
        """Access the current nesting level."""
        return self._level

    @property
    def environment(self) -> InstructionEnvironment:
        """Access the active symbolic environment."""
        return self._environment

    @property
    def namespace(self) -> Namespace:
        """Access the active routine-variable namespace."""
        return self._namespace

    @property
    def container(self) -> CodeContainer | None:
        """Return the current container or the nearest inherited one."""
        if self._container is None:
            if self.parent_context is None:
                return None
            return self.parent_context.container
        return self._container

    @property
    def library(self):
        """Access the library currently associated with the context."""
        return self._library

    @property
    def resource(self) -> ComputeResource | None:
        """Return the active compute resource, walking up the parent chain."""
        if self._resource is not None:
            return self._resource
        if self._parent_context is not None:
            return self._parent_context.resource
        return None

    def set_resource(self, resource: ComputeResource | None) -> Self:
        """
        Set the active compute resource for this context.

        :param resource: Resource to use from this context onward.
        :returns: ``self`` for chaining.
        """
        if resource is not None:
            self._resource = resource
        return self

    def set_container(self, container: CodeContainer) -> Self:
        """
        Bind the context to a concrete container once.

        :param container: Container represented by this context.
        :returns: ``self`` for chaining.
        """
        if self._container is not None:
            raise ValueError("Cannot change container once set")
        self._container = container
        return self

    def new_namespace_node(self) -> Self:
        """
        Descend into a new child namespace node.

        :returns: ``self`` for chaining.
        """
        if self._namespace is None:
            self._namespace = Namespace()
        else:
            self._namespace = self._namespace.inherit()
        return self

