    def request_resource_mfe_container(
        self,
        variable,
        name: str,
        local_variable_capture=None,
        loop_capture=None,
    ):
        """
        Request a multiframe expansion container from the active resource.

        :param variable: Multiframe selector to be expanded.
        :param name: Base name used for generated representatives.
        :param local_variable_capture: Capture container for created locals.
        :param loop_capture: Capture container coordinating loop expansion.
        :returns: Backend-specific multiframe expansion container or ``None``.
        """
        assert self.resource is not None
        assert variable is not None

        peeled_resource, mfe_container = self.resource.request_mfe_container(
            variable=variable,
            name=name,
            context=self,
            local_variable_capture=local_variable_capture,
            loop_capture=loop_capture,
        )
        self._resource = peeled_resource
        return mfe_container

    def inherit(
        self,
        name: str | None = None,
        # parent=None,
        environment: InstructionEnvironment | None = None,
        namespace: Namespace | None = None,
        resource: ComputeResource | None = None,
        # select_frame=None,
    ) -> Self:
        """
        Create a derived child context.

        :param name: Optional extra name component appended to the path.
        :param environment: Optional environment merged into the current one.
        :param namespace: Optional explicit namespace for the child.
        :param resource: Optional compute resource override for the child.
        :returns: New child context.
        """

        # if parent is None:
        #     if self.container is None:
        #         parent = self.parent
        #     else:
        #         parent = self.container

        if environment is None:
            environment = self.environment
        else:
            environment = self.environment.merge(environment)

        if namespace is None:
            if self.namespace is None:
                namespace = Namespace()
            else:
                namespace = (
                    self.namespace
                )  # .inherit()  use new_namespace_node

        # Keep resource lookup lazy through the parent chain unless an
        # explicit override is requested for the child context.

        # frame_selectors = set(self.frame_selectors)
        # if select_frame is not None:
        #     frame_selectors.add(select_frame)

        return Context(
            # parent=parent,
            level=self.level + 1,
            namespace=namespace,
            environment=environment,
            resource=resource,
            # assignments=None,
            # frame_selectors=frame_selectors,
            _names=(
                [*self._names, name] if name is not None else list(self._names)
            ),
            _library=self.library,
            _parent_context=self,
        )
